import React, { useContext, useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { useSnackbar } from "notistack";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";
import DialogContent from "@mui/material/DialogContent";
import DialogActions from "@mui/material/DialogActions";
import TextField from "@mui/material/TextField";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";
import Card from "@mui/material/Card";
import Grid from "@mui/material/Grid2";
import List from "@mui/material/List";
import ListItemButton from "@mui/material/ListItemButton";
import ListItemText from "@mui/material/ListItemText";
import IconButton from "@mui/material/IconButton";
import FormControl from "@mui/material/FormControl";
import InputLabel from "@mui/material/InputLabel";
import Select from "@mui/material/Select";
import MenuItem from "@mui/material/MenuItem";
import Alert from "@mui/material/Alert";
import Checkbox from "@mui/material/Checkbox";
import AddOutlined from "@mui/icons-material/AddOutlined";
import EditOutlined from "@mui/icons-material/EditOutlined";
import DeleteOutlined from "@mui/icons-material/DeleteOutlined";
import DeleteSweepOutlined from "@mui/icons-material/DeleteSweepOutlined";
import MenuBookOutlined from "@mui/icons-material/MenuBookOutlined";
import ImageOutlined from "@mui/icons-material/ImageOutlined";
import CircularProgress from "@mui/material/CircularProgress";
import CheckCircleOutlined from "@mui/icons-material/CheckCircleOutlined";
import DownloadOutlined from "@mui/icons-material/DownloadOutlined";
import UploadFileOutlined from "@mui/icons-material/UploadFileOutlined";
import CloseOutlined from "@mui/icons-material/CloseOutlined";
import CheckOutlined from "@mui/icons-material/CheckOutlined";
import { DataGrid, GridColDef, GridActionsCellItem, GridRowSelectionModel } from "@mui/x-data-grid";
import { AppContext, reUseBlocContent } from "../../../base/AppContext";
import AppDialog from "../../components/dialogs/AppDialog";
import { DIALOG_CANCEL_BUTTON_SX, DIALOG_PRIMARY_BUTTON_SX } from "../../components/dialogs/dialogToneStyles";
import SubjectLibraryDialog from "../../components/common/SubjectLibraryDialog";
import { BlocParentSubjects, QuizSubject, QuizLesson, QuizClassroomLite, QuizLessonImportResult, QuizSubjectImportResult } from "../../bloc/BlocParentSubjects";
import UIStream from "../../components/common/UIStream";
import { quizErrorMessage } from "../../../quiz-net/quizErrors";

// Trang "Môn học / Bài học" (khu vực Phụ huynh, /app/parent/subjects - Task 3 backend). Master-
// detail 1 màn hình: cột trái danh sách Subject (List), chọn 1 Subject thì cột phải hiện Lesson
// của Subject đó (DataGrid) - cả 2 phần dùng chung 1 Bloc (BlocParentSubjects) nhưng nhiều stream
// riêng, theo đúng lưu ý ở ui-base-status.md: Dialog phải nằm trong builder() của UIStream, không
// phải children.
//
// STATE MANAGEMENT (đổi 2026-09-01, xem claude/ui-base-status.md "Quy ước state mới") - TOÀN BỘ
// useState cũ (filterClassroomId/selectedSubject/subjectForm/lessonForm/submitting/ảnh...) dời
// vào BlocParentSubjects, xem comment "State giao diện dời từ useState vào đây" ở đó cho chi tiết
// từng stream. selectedSubject bọc UIStream NGOÀI CÙNG (cả 2 cột trái/phải đều phụ thuộc), các
// Dialog + field cần phản ứng live (Select) bọc UIStream hẹp riêng, TextField thường uncontrolled.
export default function Subjects() {
    const { t } = useTranslation();
    const { enqueueSnackbar } = useSnackbar();
    const appContext = useContext(AppContext);
    const bloc = reUseBlocContent(appContext, BlocParentSubjects);
    const showError = (error: any) => enqueueSnackbar(quizErrorMessage(t, error), { variant: error?.variant ?? 'error' });

    useEffect(() => {
        bloc.initData();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const saveSubject = () => {
        bloc.saveSubject(() => bloc.closeSubjectForm(), showError);
    };

    const askRemoveSubject = (subject: QuizSubject) => {
        bloc.confirm({
            title: 'delete',
            message: 'quiz-delete-subject-confirm',
            onYes: () => {
                bloc.removeSubject(subject.id, () => {
                    enqueueSnackbar(t('quiz-subject-deleted') as string, { variant: 'success' });
                    bloc.askRemoveSubjectCleanup(subject.id);
                }, showError);
            }
        });
    };

    // Xoá nhiều Môn học (2026-09-06, "xoa muon hoc") - "Xoá đã chọn"/"Xoá tất cả" ở cột trái.
    const askRemoveSubjects = (ids: number[]) => {
        if (ids.length === 0) return;
        bloc.confirm({
            title: 'delete',
            message: t('quiz-delete-selected-subjects-confirm', { count: ids.length }) as string,
            onYes: () => {
                bloc.removeSubjects(ids, (result) => {
                    enqueueSnackbar(t('quiz-subjects-bulk-deleted', { deleted: result.deletedCount, total: result.requested }) as string,
                        { variant: result.deletedCount === result.requested ? 'success' : 'warning' });
                }, showError);
            }
        });
    };

    const saveLesson = (subjectId: number) => {
        bloc.saveLesson(subjectId, () => bloc.closeLessonForm(), showError);
    };

    const onImageFileSelected = (subjectId: number) => (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        e.target.value = '';
        if (!file) return;
        bloc.uploadImageForCurrentLesson(subjectId, file, showError);
    };

    const removeLessonImage = (subjectId: number) => {
        bloc.removeImageForCurrentLesson(subjectId, showError);
    };

    const lessonFileInputRef = useRef<HTMLInputElement>(null);
    const subjectFileInputRef = useRef<HTMLInputElement>(null);

    // Which subject's textbook-library dialog is open (2026-09-05) - plain local state, not a
    // bloc stream: SubjectLibraryDialog.tsx reuses THIS page's bloc (BlocParentSubjects) for its
    // data since reUseBlocContent only keeps one content bloc per page (see AppContext.ts), but
    // "which subject is the dialog currently for" is pure UI state local to this page.
    const [libraryDialogSubject, setLibraryDialogSubject] = useState<QuizSubject | null>(null);

    const downloadLessonTemplate = (format: 'xlsx' | 'csv') => bloc.downloadLessonImportTemplate(format, showError);

    const onLessonImportFileChosen = (subjectId: number) => (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        e.target.value = '';
        if (!file) return;
        bloc.runLessonImport(subjectId, file, showError);
    };

    const downloadSubjectTemplate = (format: 'xlsx' | 'csv') => bloc.downloadSubjectImportTemplate(format, showError);

    const onSubjectImportFileChosen = (classroomId: number | '') => (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        e.target.value = '';
        if (!file || classroomId === '') return;
        bloc.runSubjectImport(classroomId, file, showError);
    };

    const askRemoveLesson = (lesson: QuizLesson, subjectId: number) => {
        bloc.confirm({
            title: 'delete',
            message: 'quiz-delete-lesson-confirm',
            onYes: () => {
                bloc.removeLesson(lesson.id, subjectId, () => {
                    enqueueSnackbar(t('quiz-lesson-deleted') as string, { variant: 'success' });
                }, showError);
            }
        });
    };

    // Xoá nhiều Bài học (2026-09-06, "xoa bai cua muon hoc") - "Xoá đã chọn"/"Xoá tất cả" ở
    // DataGrid cột phải.
    const askRemoveLessons = (ids: number[], subjectId: number) => {
        if (ids.length === 0) return;
        bloc.confirm({
            title: 'delete',
            message: t('quiz-delete-selected-lessons-confirm', { count: ids.length }) as string,
            onYes: () => {
                bloc.removeLessons(ids, subjectId, (result) => {
                    enqueueSnackbar(t('quiz-lessons-bulk-deleted', { deleted: result.deletedCount, total: result.requested }) as string,
                        { variant: result.deletedCount === result.requested ? 'success' : 'warning' });
                }, showError);
            }
        });
    };

    const lessonColumns = (subjectId: number): GridColDef[] => [
        { field: 'name', headerName: t('quiz-lesson-name') as string, flex: 1, minWidth: 200 },
        {
            field: 'textbookPage', headerName: t('quiz-lesson-textbook-page') as string, width: 110,
            valueGetter: (_value, row) => (row as QuizLesson).textbookPage ?? ''
        },
        {
            field: 'hasImage', headerName: t('quiz-lesson-image') as string, width: 80, sortable: false,
            renderCell: (params) => (params.row as QuizLesson).hasImage
                ? <CheckCircleOutlined fontSize="small" color="success" />
                : null
        },
        {
            field: 'actions', type: 'actions', headerName: t('actions') as string, width: 100,
            getActions: (params) => [
                <GridActionsCellItem icon={<EditOutlined fontSize="small" />} label="edit" onClick={() => bloc.openEditLesson(params.row)} />,
                <GridActionsCellItem icon={<DeleteOutlined fontSize="small" />} label="delete" onClick={() => askRemoveLesson(params.row, subjectId)} />
            ]
        }
    ];

    return (
        <UIStream
            initialData={bloc.getField('selectedSubject') ?? null}
            stream={bloc.getStream('selectedSubject')}
            builder={(selectedSnap) => {
                const selectedSubject: QuizSubject | null = selectedSnap.data ?? null;
                // KHÔNG dùng useMemo ở đây - đây là closure builder() của UIStream, được gọi từ
                // render() của 1 class component (UIStream.ts), không phải function component nên
                // không được gọi hook (vi phạm Rules of Hooks). Mảng cột nhỏ, tạo lại mỗi lần
                // 'selectedSubject' đổi (không phải mỗi phím gõ) là chấp nhận được.
                const lessonColumnsMemo = selectedSubject ? lessonColumns(selectedSubject.id) : [];

                return (
                    <>
                    <Grid container spacing={2}>
                        <Grid size={{ xs: 12, md: 4 }}>
                            <UIStream
                                initialData={null}
                                stream={bloc.getStream('subjects')}
                                builder={(snapshot) => {
                                    const subjects: QuizSubject[] = snapshot.data ?? [];
                                    return (
                                        <>
                                            <Card sx={{ p: 2 }}>
                                                <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ mb: 1 }}>
                                                    <Typography variant="h6" fontWeight={700}>{t('quiz-subjects')}</Typography>
                                                    <Stack direction="row">
                                                        <IconButton color="primary" onClick={() => bloc.openSubjectImport()}><UploadFileOutlined /></IconButton>
                                                        <IconButton color="primary" onClick={() => bloc.openNewSubject()}><AddOutlined /></IconButton>
                                                    </Stack>
                                                </Stack>
                                                <UIStream
                                                    initialData={[]}
                                                    stream={bloc.getStream('subjectSelection')}
                                                    builder={(subjectSelSnap) => {
                                                        const selectedSubjectIds: number[] = subjectSelSnap.data ?? [];
                                                        return (
                                                            <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" rowGap={0.5} sx={{ mb: 1 }}>
                                                                {selectedSubjectIds.length > 0 && (
                                                                    <Typography variant="caption" color="text.secondary">
                                                                        {t('quiz-selected-count', { count: selectedSubjectIds.length })}
                                                                    </Typography>
                                                                )}
                                                                <Button size="small" color="error" startIcon={<DeleteOutlined />} disabled={selectedSubjectIds.length === 0} onClick={() => askRemoveSubjects(selectedSubjectIds)}>
                                                                    {t('quiz-delete-selected')}
                                                                </Button>
                                                                <Button size="small" color="error" startIcon={<DeleteSweepOutlined />} disabled={subjects.length === 0} onClick={() => askRemoveSubjects(subjects.map((s) => s.id))}>
                                                                    {t('quiz-delete-all')}
                                                                </Button>
                                                            </Stack>
                                                        );
                                                    }}
                                                />
                                                <UIStream
                                                    initialData={bloc.getField('classrooms')}
                                                    stream={bloc.getStream('classrooms')}
                                                    builder={(classroomsSnap) => {
                                                        // Cần classroomsSnap ở CẢ Select lọc lẫn List bên dưới (mỗi Subject hiện kèm
                                                        // tên Lớp) nên bọc chung 1 UIStream ngoài cùng thay vì lồng riêng cho Select
                                                        // như trước - lý do anh test thấy 2 môn cùng tên "Toán" không phân biệt được
                                                        // thuộc Lớp nào khi lọc "Tất cả lớp" (2026-09-01).
                                                        const classrooms: QuizClassroomLite[] = classroomsSnap.data ?? [];
                                                        // classroomId null (2026-09-06 (c)) = Môn dùng chung mọi Lớp - hiện nhãn riêng
                                                        // thay vì để trống, xem QuizSubject.classroomId's comment.
                                                        const classroomName = (classroomId: number | null) =>
                                                            classroomId == null ? t('quiz-subject-shared-all-classrooms') : (classrooms.find((c) => c.id === classroomId)?.name ?? '');
                                                        return (
                                                            <>
                                                                <UIStream
                                                                    initialData={bloc.getField('filterClassroomId') ?? ''}
                                                                    stream={bloc.getStream('filterClassroomId')}
                                                                    builder={(filterSnap) => (
                                                                        <FormControl fullWidth size="small" sx={{ mb: 1 }}>
                                                                            <InputLabel>{t('quiz-classrooms')}</InputLabel>
                                                                            <Select
                                                                                label={t('quiz-classrooms')}
                                                                                value={filterSnap.data ?? ''}
                                                                                onChange={(e) => bloc.changeFilterClassroom(e.target.value === '' ? '' : Number(e.target.value))}
                                                                            >
                                                                                <MenuItem value="">{t('quiz-all-classrooms')}</MenuItem>
                                                                                {classrooms.map((c: QuizClassroomLite) => <MenuItem key={c.id} value={c.id}>{c.name}</MenuItem>)}
                                                                            </Select>
                                                                        </FormControl>
                                                                    )}
                                                                />
                                                                <UIStream
                                                                    initialData={[]}
                                                                    stream={bloc.getStream('subjectSelection')}
                                                                    builder={(subjectSelSnap2) => {
                                                                        const selectedSubjectIds2: number[] = subjectSelSnap2.data ?? [];
                                                                        return (
                                                                            <List disablePadding>
                                                                                {subjects.map((s) => (
                                                                                    <ListItemButton
                                                                                        key={s.id}
                                                                                        selected={selectedSubject?.id === s.id}
                                                                                        onClick={() => bloc.selectSubject(s)}
                                                                                        sx={{ borderRadius: 1, mb: 0.5 }}
                                                                                    >
                                                                                        <Checkbox
                                                                                            size="small"
                                                                                            edge="start"
                                                                                            checked={selectedSubjectIds2.includes(s.id)}
                                                                                            onClick={(e) => e.stopPropagation()}
                                                                                            onChange={() => bloc.toggleSubjectSelection(s.id)}
                                                                                        />
                                                                                        <ListItemText primary={s.name} secondary={classroomName(s.classroomId)} />
                                                                                        <IconButton size="small" onClick={(e) => { e.stopPropagation(); setLibraryDialogSubject(s); }}>
                                                                                            <MenuBookOutlined fontSize="small" />
                                                                                        </IconButton>
                                                                                        <IconButton size="small" onClick={(e) => { e.stopPropagation(); bloc.openEditSubject(s); }}>
                                                                                            <EditOutlined fontSize="small" />
                                                                                        </IconButton>
                                                                                        <IconButton size="small" onClick={(e) => { e.stopPropagation(); askRemoveSubject(s); }}>
                                                                                            <DeleteOutlined fontSize="small" />
                                                                                        </IconButton>
                                                                                    </ListItemButton>
                                                                                ))}
                                                                                {subjects.length === 0 && snapshot.data != null && (
                                                                                    <Typography variant="body2" color="text.secondary" sx={{ p: 1 }}>
                                                                                        {t('quiz-no-subjects')}
                                                                                    </Typography>
                                                                                )}
                                                                            </List>
                                                                        );
                                                                    }}
                                                                />
                                                            </>
                                                        );
                                                    }}
                                                />
                                            </Card>

                                            <UIStream
                                                initialData={{ isShow: false, id: 0 }}
                                                stream={bloc.getStream('subject_form_view')}
                                                builder={(viewSnap) => {
                                                    const view = viewSnap.data ?? { isShow: false, id: 0 };
                                                    const isEditing = (view.id ?? 0) > 0;
                                                    return (
                                                        <AppDialog open={view.isShow === true} onClose={() => bloc.closeSubjectForm()} maxWidth="xs" title={isEditing ? t('quiz-subject-edit') : t('quiz-subject-new')} icon={isEditing ? EditOutlined : AddOutlined}>
                                                            <DialogContent>
                                                                <Stack spacing={2} sx={{ mt: 1 }}>
                                                                    <UIStream
                                                                        initialData={bloc.getField('classrooms')}
                                                                        stream={bloc.getStream('classrooms')}
                                                                        builder={(classroomsSnap) => (
                                                                            <UIStream
                                                                                initialData={bloc.getField('subjectFormClassroomId', 'subjectReq') ?? ''}
                                                                                stream={bloc.getStream('subjectFormClassroomId')}
                                                                                builder={(classroomIdSnap) => (
                                                                                    <FormControl fullWidth size="small">
                                                                                        <InputLabel>{t('quiz-classrooms')}</InputLabel>
                                                                                        <Select
                                                                                            label={t('quiz-classrooms')}
                                                                                            value={classroomIdSnap.data ?? ''}
                                                                                            onChange={(e) => {
                                                                                                const v = e.target.value;
                                                                                                bloc.setStream('subjectFormClassroomId', v === '' ? '' : (v === 'ALL' ? 'ALL' : Number(v)), 'subjectReq')
                                                                                            }}
                                                                                        >
                                                                                            {/* 'ALL' (2026-09-06 (c)) = Môn dùng chung mọi Lớp của Phụ huynh - chuyển thành
                                                                                                classroomId=null khi lưu, xem BlocParentSubjects.saveSubject. */}
                                                                                            <MenuItem value="ALL">{t('quiz-subject-shared-all-classrooms')}</MenuItem>
                                                                                            {(classroomsSnap.data ?? []).map((c: QuizClassroomLite) => <MenuItem key={c.id} value={c.id}>{c.name}</MenuItem>)}
                                                                                        </Select>
                                                                                    </FormControl>
                                                                                )}
                                                                            />
                                                                        )}
                                                                    />
                                                                    <TextField
                                                                        label={t('quiz-subject-name')}
                                                                        defaultValue={bloc.getField('subjectFormName', 'subjectReq') ?? ''}
                                                                        onChange={(e) => bloc.setStream('subjectFormName', e.target.value, 'subjectReq')}
                                                                        autoFocus
                                                                        fullWidth
                                                                    />
                                                                </Stack>
                                                            </DialogContent>
                                                            <DialogActions>
                                                                <Button onClick={() => bloc.closeSubjectForm()} variant="contained" startIcon={<CloseOutlined />} sx={DIALOG_CANCEL_BUTTON_SX}>{t('cancel')}</Button>
                                                                <UIStream
                                                                    initialData={false}
                                                                    stream={bloc.getStream('submitting')}
                                                                    builder={(submittingSnap) => (
                                                                        <Button variant="contained" color="primary" startIcon={<CheckOutlined />} disabled={submittingSnap.data === true} onClick={saveSubject} sx={DIALOG_PRIMARY_BUTTON_SX}>{t('save')}</Button>
                                                                    )}
                                                                />
                                                            </DialogActions>
                                                        </AppDialog>
                                                    );
                                                }}
                                            />

                                            <UIStream
                                                initialData={{ isShow: false }}
                                                stream={bloc.getStream('subject_import_view')}
                                                builder={(viewSnap) => {
                                                    const view = viewSnap.data ?? { isShow: false };
                                                    return (
                                                        <AppDialog open={view.isShow === true} onClose={() => bloc.closeSubjectImport()} maxWidth="xs" title={t('quiz-import-subjects-dialog-title')} icon={UploadFileOutlined}>
                                                            <DialogContent>
                                                                <Stack spacing={2} sx={{ mt: 1 }} alignItems="flex-start">
                                                                    <Typography variant="body2" color="text.secondary">{t('quiz-import-subjects-hint')}</Typography>
                                                                    <UIStream
                                                                        initialData={bloc.getField('classrooms')}
                                                                        stream={bloc.getStream('classrooms')}
                                                                        builder={(classroomsSnap) => (
                                                                            <UIStream
                                                                                initialData={bloc.getField('subjectImportClassroomId') ?? ''}
                                                                                stream={bloc.getStream('subjectImportClassroomId')}
                                                                                builder={(classroomIdSnap) => (
                                                                                    <FormControl fullWidth size="small">
                                                                                        <InputLabel>{t('quiz-classrooms')}</InputLabel>
                                                                                        <Select
                                                                                            label={t('quiz-classrooms')}
                                                                                            value={classroomIdSnap.data ?? ''}
                                                                                            onChange={(e) => bloc.setStream('subjectImportClassroomId', e.target.value === '' ? '' : Number(e.target.value))}
                                                                                        >
                                                                                            {(classroomsSnap.data ?? []).map((c: QuizClassroomLite) => <MenuItem key={c.id} value={c.id}>{c.name}</MenuItem>)}
                                                                                        </Select>
                                                                                    </FormControl>
                                                                                )}
                                                                            />
                                                                        )}
                                                                    />
                                                                    <Stack direction="row" spacing={1}>
                                                                        <Button size="small" startIcon={<DownloadOutlined />} onClick={() => downloadSubjectTemplate('xlsx')}>{t('quiz-download-template-xlsx')}</Button>
                                                                        <Button size="small" startIcon={<DownloadOutlined />} onClick={() => downloadSubjectTemplate('csv')}>{t('quiz-download-template-csv')}</Button>
                                                                    </Stack>
                                                                    <UIStream
                                                                        initialData={false}
                                                                        stream={bloc.getStream('subjectImporting')}
                                                                        builder={(importingSnap) => (
                                                                            <UIStream
                                                                                initialData={bloc.getField('subjectImportClassroomId') ?? ''}
                                                                                stream={bloc.getStream('subjectImportClassroomId')}
                                                                                builder={(classroomIdSnap) => (
                                                                                    <>
                                                                                        <input ref={subjectFileInputRef} type="file" accept=".xlsx,.csv" hidden onChange={onSubjectImportFileChosen(classroomIdSnap.data ?? '')} />
                                                                                        <Button
                                                                                            variant="outlined"
                                                                                            startIcon={importingSnap.data === true ? <CircularProgress size={16} /> : <UploadFileOutlined />}
                                                                                            disabled={importingSnap.data === true || !classroomIdSnap.data}
                                                                                            onClick={() => subjectFileInputRef.current?.click()}
                                                                                        >
                                                                                            {t('quiz-import-pick-file')}
                                                                                        </Button>
                                                                                    </>
                                                                                )}
                                                                            />
                                                                        )}
                                                                    />
                                                                    <UIStream
                                                                        initialData={null}
                                                                        stream={bloc.getStream('subjectImportResult')}
                                                                        builder={(resultSnap) => {
                                                                            const importResult: QuizSubjectImportResult | null = resultSnap.data;
                                                                            if (!importResult) return null;
                                                                            return (
                                                                                <Alert severity={importResult.errors.length === 0 ? 'success' : 'warning'} sx={{ width: '100%' }}>
                                                                                    {t('quiz-import-result-summary', { success: importResult.successCount, total: importResult.totalRows })}
                                                                                    {importResult.errors.length > 0 && (
                                                                                        <Box component="ul" sx={{ m: 0, mt: 1, pl: 2 }}>
                                                                                            {importResult.errors.map((err, i) => (
                                                                                                <li key={i}>
                                                                                                    <Typography variant="body2">
                                                                                                        {t('quiz-import-row-error', { row: err.rowNumber, reason: err.reason })}
                                                                                                    </Typography>
                                                                                                </li>
                                                                                            ))}
                                                                                        </Box>
                                                                                    )}
                                                                                </Alert>
                                                                            );
                                                                        }}
                                                                    />
                                                                </Stack>
                                                            </DialogContent>
                                                            <DialogActions>
                                                                <Button onClick={() => bloc.closeSubjectImport()} variant="contained" color="primary" startIcon={<CloseOutlined />} sx={DIALOG_PRIMARY_BUTTON_SX}>{t('close')}</Button>
                                                            </DialogActions>
                                                        </AppDialog>
                                                    );
                                                }}
                                            />
                                        </>
                                    );
                                }}
                            />
                        </Grid>

                        <Grid size={{ xs: 12, md: 8 }}>
                            {selectedSubject == null ? (
                                <Card sx={{
                                    p: 4, display: 'flex', flexDirection: 'column', alignItems: 'center',
                                    justifyContent: 'center', minHeight: 240, color: 'text.secondary'
                                }}>
                                    <MenuBookOutlined sx={{ fontSize: 48, mb: 1, opacity: 0.5 }} />
                                    <Typography variant="body1">{t('quiz-select-subject-hint')}</Typography>
                                </Card>
                            ) : (
                                <UIStream
                                    initialData={null}
                                    stream={bloc.getStream('lessons')}
                                    builder={(snapshot) => {
                                        const lessons: QuizLesson[] = snapshot.data ?? [];
                                        return (
                                            <>
                                                <UIStream
                                                    initialData={[]}
                                                    stream={bloc.getStream('lessonSelection')}
                                                    builder={(lessonSelSnap) => {
                                                        const selectedLessonIds: number[] = lessonSelSnap.data ?? [];
                                                        return (
                                                            <Card sx={{ p: { xs: 2, sm: 3 } }}>
                                                                <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ mb: 2 }} flexWrap="wrap" rowGap={1}>
                                                                    <Typography variant="h6" fontWeight={700}>
                                                                        {t('quiz-lessons-of', { subject: selectedSubject.name })}
                                                                    </Typography>
                                                                    <Stack direction="row" spacing={1} flexWrap="wrap" alignItems="center">
                                                                        {selectedLessonIds.length > 0 && (
                                                                            <Typography variant="body2" color="text.secondary">
                                                                                {t('quiz-selected-count', { count: selectedLessonIds.length })}
                                                                            </Typography>
                                                                        )}
                                                                        <Button size="small" color="error" startIcon={<DeleteOutlined />} disabled={selectedLessonIds.length === 0} onClick={() => askRemoveLessons(selectedLessonIds, selectedSubject.id)}>
                                                                            {t('quiz-delete-selected')}
                                                                        </Button>
                                                                        <Button size="small" color="error" startIcon={<DeleteSweepOutlined />} disabled={lessons.length === 0} onClick={() => askRemoveLessons(lessons.map((l) => l.id), selectedSubject.id)}>
                                                                            {t('quiz-delete-all')}
                                                                        </Button>
                                                                        <Button size="small" startIcon={<DownloadOutlined />} onClick={() => downloadLessonTemplate('xlsx')}>{t('quiz-download-template-xlsx')}</Button>
                                                                        <Button size="small" startIcon={<DownloadOutlined />} onClick={() => downloadLessonTemplate('csv')}>{t('quiz-download-template-csv')}</Button>
                                                                        <Button size="small" variant="outlined" startIcon={<UploadFileOutlined />} onClick={() => bloc.openLessonImport()}>{t('quiz-import-lessons')}</Button>
                                                                        <Button variant="contained" startIcon={<AddOutlined />} onClick={() => bloc.openNewLesson()}>{t('new')}</Button>
                                                                    </Stack>
                                                                </Stack>
                                                                <Box sx={{ height: 380 }}>
                                                                    <DataGrid
                                                                        rows={lessons}
                                                                        columns={lessonColumnsMemo}
                                                                        loading={snapshot.data == null}
                                                                        disableRowSelectionOnClick
                                                                        checkboxSelection
                                                                        rowSelectionModel={selectedLessonIds}
                                                                        onRowSelectionModelChange={(model: GridRowSelectionModel) => bloc.changeLessonSelection(model as number[])}
                                                                    />
                                                                </Box>
                                                            </Card>
                                                        );
                                                    }}
                                                />

                                                <UIStream
                                                    initialData={{ isShow: false, id: 0 }}
                                                    stream={bloc.getStream('lesson_form_view')}
                                                    builder={(viewSnap) => {
                                                        const view = viewSnap.data ?? { isShow: false, id: 0 };
                                                        const isEditing = (view.id ?? 0) > 0;
                                                        return (
                                                            <AppDialog open={view.isShow === true} onClose={() => bloc.closeLessonForm()} maxWidth="sm" title={isEditing ? t('quiz-lesson-edit') : t('quiz-lesson-new')} icon={isEditing ? EditOutlined : AddOutlined}>
                                                                <DialogContent>
                                                                    <Stack spacing={2} sx={{ mt: 1 }}>
                                                                        <TextField
                                                                            label={t('quiz-lesson-name')}
                                                                            defaultValue={bloc.getField('lessonName', 'lessonReq') ?? ''}
                                                                            onChange={(e) => bloc.setStream('lessonName', e.target.value, 'lessonReq')}
                                                                            autoFocus
                                                                            fullWidth
                                                                        />
                                                                        <TextField
                                                                            label={t('quiz-lesson-summary')}
                                                                            defaultValue={bloc.getField('lessonSummary', 'lessonReq') ?? ''}
                                                                            onChange={(e) => bloc.setStream('lessonSummary', e.target.value, 'lessonReq')}
                                                                            fullWidth
                                                                            multiline
                                                                            minRows={2}
                                                                            helperText={t('quiz-lesson-summary-hint')}
                                                                        />
                                                                        <TextField
                                                                            label={t('quiz-lesson-content')}
                                                                            defaultValue={bloc.getField('lessonContent', 'lessonReq') ?? ''}
                                                                            onChange={(e) => bloc.setStream('lessonContent', e.target.value, 'lessonReq')}
                                                                            fullWidth
                                                                            multiline
                                                                            minRows={4}
                                                                            helperText={t('quiz-lesson-content-hint')}
                                                                        />
                                                                        <TextField
                                                                            label={t('quiz-lesson-textbook-page')}
                                                                            type="number"
                                                                            defaultValue={bloc.getField('lessonTextbookPage', 'lessonReq') ?? ''}
                                                                            onChange={(e) => bloc.setStream('lessonTextbookPage', e.target.value === '' ? '' : Number(e.target.value), 'lessonReq')}
                                                                            fullWidth
                                                                            sx={{ maxWidth: 200 }}
                                                                            inputProps={{ min: 1 }}
                                                                        />

                                                                        <Box>
                                                                            <Typography variant="subtitle2" sx={{ mb: 1 }}>{t('quiz-lesson-image')}</Typography>
                                                                            {!isEditing ? (
                                                                                <Typography variant="body2" color="text.secondary">{t('quiz-lesson-image-save-first')}</Typography>
                                                                            ) : (
                                                                                <Stack direction="row" spacing={2} alignItems="center">
                                                                                    <UIStream
                                                                                        initialData={false}
                                                                                        stream={bloc.getStream('lessonImageLoading')}
                                                                                        builder={(loadingSnap) => (
                                                                                            loadingSnap.data === true ? (
                                                                                                <CircularProgress size={64} />
                                                                                            ) : (
                                                                                                <UIStream
                                                                                                    initialData={null}
                                                                                                    stream={bloc.getStream('lessonImagePreviewUrl')}
                                                                                                    builder={(urlSnap) => (
                                                                                                        urlSnap.data ? (
                                                                                                            <Box
                                                                                                                component="img"
                                                                                                                src={urlSnap.data}
                                                                                                                alt=""
                                                                                                                sx={{ width: 96, height: 96, objectFit: 'cover', borderRadius: 1, border: '1px solid', borderColor: 'divider' }}
                                                                                                            />
                                                                                                        ) : (
                                                                                                            <Box sx={{
                                                                                                                width: 96, height: 96, borderRadius: 1, border: '1px dashed',
                                                                                                                borderColor: 'divider', display: 'flex', alignItems: 'center', justifyContent: 'center'
                                                                                                            }}>
                                                                                                                <ImageOutlined color="disabled" />
                                                                                                            </Box>
                                                                                                        )
                                                                                                    )}
                                                                                                />
                                                                                            )
                                                                                        )}
                                                                                    />
                                                                                    <Stack spacing={1}>
                                                                                        <UIStream
                                                                                            initialData={false}
                                                                                            stream={bloc.getStream('lessonImageUploading')}
                                                                                            builder={(uploadingSnap) => (
                                                                                                <Button
                                                                                                    component="label"
                                                                                                    variant="outlined"
                                                                                                    size="small"
                                                                                                    startIcon={<ImageOutlined />}
                                                                                                    disabled={uploadingSnap.data === true}
                                                                                                >
                                                                                                    {uploadingSnap.data === true ? t('quiz-lesson-image-uploading') : t('quiz-lesson-image-upload')}
                                                                                                    <input type="file" accept="image/jpeg,image/png,image/webp" hidden onChange={onImageFileSelected(selectedSubject.id)} />
                                                                                                </Button>
                                                                                            )}
                                                                                        />
                                                                                        <UIStream
                                                                                            initialData={false}
                                                                                            stream={bloc.getStream('lessonHasImage')}
                                                                                            builder={(hasImageSnap) => (
                                                                                                hasImageSnap.data === true ? (
                                                                                                    <Button color="error" size="small" onClick={() => removeLessonImage(selectedSubject.id)}>
                                                                                                        {t('quiz-lesson-image-remove')}
                                                                                                    </Button>
                                                                                                ) : null
                                                                                            )}
                                                                                        />
                                                                                    </Stack>
                                                                                </Stack>
                                                                            )}
                                                                        </Box>
                                                                    </Stack>
                                                                </DialogContent>
                                                                <DialogActions>
                                                                    <Button onClick={() => bloc.closeLessonForm()} variant="contained" startIcon={<CloseOutlined />} sx={DIALOG_CANCEL_BUTTON_SX}>{t('cancel')}</Button>
                                                                    <UIStream
                                                                        initialData={false}
                                                                        stream={bloc.getStream('submitting')}
                                                                        builder={(submittingSnap) => (
                                                                            <Button variant="contained" color="primary" startIcon={<CheckOutlined />} disabled={submittingSnap.data === true} onClick={() => saveLesson(selectedSubject.id)} sx={DIALOG_PRIMARY_BUTTON_SX}>{t('save')}</Button>
                                                                        )}
                                                                    />
                                                                </DialogActions>
                                                            </AppDialog>
                                                        );
                                                    }}
                                                />

                                                <UIStream
                                                    initialData={{ isShow: false }}
                                                    stream={bloc.getStream('lesson_import_view')}
                                                    builder={(viewSnap) => {
                                                        const view = viewSnap.data ?? { isShow: false };
                                                        return (
                                                            <AppDialog open={view.isShow === true} onClose={() => bloc.closeLessonImport()} maxWidth="xs" title={t('quiz-import-lessons-dialog-title')} icon={UploadFileOutlined}>
                                                                <DialogContent>
                                                                    <input ref={lessonFileInputRef} type="file" accept=".xlsx,.csv" hidden onChange={onLessonImportFileChosen(selectedSubject.id)} />
                                                                    <Stack spacing={2} sx={{ mt: 1 }} alignItems="flex-start">
                                                                        <Typography variant="body2" color="text.secondary">{t('quiz-import-lessons-hint')}</Typography>
                                                                        <UIStream
                                                                            initialData={false}
                                                                            stream={bloc.getStream('lessonImporting')}
                                                                            builder={(importingSnap) => (
                                                                                <Button
                                                                                    variant="outlined"
                                                                                    startIcon={importingSnap.data === true ? <CircularProgress size={16} /> : <UploadFileOutlined />}
                                                                                    disabled={importingSnap.data === true}
                                                                                    onClick={() => lessonFileInputRef.current?.click()}
                                                                                >
                                                                                    {t('quiz-import-pick-file')}
                                                                                </Button>
                                                                            )}
                                                                        />
                                                                        <UIStream
                                                                            initialData={null}
                                                                            stream={bloc.getStream('lessonImportResult')}
                                                                            builder={(resultSnap) => {
                                                                                const importResult: QuizLessonImportResult | null = resultSnap.data;
                                                                                if (!importResult) return null;
                                                                                return (
                                                                                    <Alert severity={importResult.errors.length === 0 ? 'success' : 'warning'} sx={{ width: '100%' }}>
                                                                                        {t('quiz-import-result-summary', { success: importResult.successCount, total: importResult.totalRows })}
                                                                                        {importResult.errors.length > 0 && (
                                                                                            <Box component="ul" sx={{ m: 0, mt: 1, pl: 2 }}>
                                                                                                {importResult.errors.map((err, i) => (
                                                                                                    <li key={i}>
                                                                                                        <Typography variant="body2">
                                                                                                            {t('quiz-import-row-error', { row: err.rowNumber, reason: err.reason })}
                                                                                                        </Typography>
                                                                                                    </li>
                                                                                                ))}
                                                                                            </Box>
                                                                                        )}
                                                                                    </Alert>
                                                                                );
                                                                            }}
                                                                        />
                                                                    </Stack>
                                                                </DialogContent>
                                                                <DialogActions>
                                                                    <Button onClick={() => bloc.closeLessonImport()} variant="contained" color="primary" startIcon={<CloseOutlined />} sx={DIALOG_PRIMARY_BUTTON_SX}>{t('close')}</Button>
                                                                </DialogActions>
                                                            </AppDialog>
                                                        );
                                                    }}
                                                />
                                            </>
                                        );
                                    }}
                                />
                            )}
                        </Grid>
                    </Grid>
                    <SubjectLibraryDialog
                        bloc={bloc}
                        subjectId={libraryDialogSubject?.id ?? null}
                        subjectName={libraryDialogSubject?.name ?? ''}
                        open={libraryDialogSubject != null}
                        onClose={() => setLibraryDialogSubject(null)}
                    />
                    </>
                );
            }}
        />
    );
}
